-- 3. INSERT ALL FAQS (9 records)
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (1, 'How do I upload a document?', 'Navigate to the ''Verify Document'' page, drag and drop your document file (PNG, JPG, or PDF), confirm the consent declaration, and click ''Initiate Verification Pipeline''.', 'General', TRUE, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (2, 'What documents are supported?', 'We currently support academic degrees, diplomas, transcripts, and official institutional certificates up to 10MB in PNG, JPG, JPEG, and PDF formats.', 'General', TRUE, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (3, 'Why is my document suspicious?', 'A document is classified as ''Suspicious'' when minor discrepancies exist (such as date formats, partial name spelling variances, or compression artifacts) without definitive proof of forgery.', 'Forensics', TRUE, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (4, 'What does risk score mean?', 'The risk score is an explainable 0 to 100 rating computed by our deterministic rules engine. 0–20 indicates LOW risk, 21–50 is MEDIUM risk, and 51–100 is HIGH risk.', 'Risk Engine', TRUE, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (5, 'Why did OCR fail?', 'OCR may encounter difficulty if the uploaded scan has severe motion blur, low lighting, or resolution under 150 DPI. We recommend uploading a straight, high-contrast scan.', 'OCR', TRUE, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (6, 'What is blockchain verification?', 'Our system computes an immutable SHA-256 cryptographic digest of your document and registers a verification receipt on an EVM-compatible blockchain ledger. No private personal data or original images are ever stored on-chain.', 'Blockchain', TRUE, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (7, 'How do I verify a QR receipt?', 'Each verified document issues a cryptographic receipt containing a QR code. Scanning the QR code directs to a public verification portal displaying tamper-proof ledger validation.', 'Verification', TRUE, 7) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (8, 'Where is my verification ID?', 'Your verification ID is generated in the format ''VRF-2026-XXXXX'' immediately upon submission and is prominently displayed on the verification result screen, downloadable receipt, and your personal user dashboard.', 'General', TRUE, 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.faqs (id, question, answer, category, is_enabled, sort_order) VALUES (9, 'What does the heatmap mean?', 'The forensic heatmap provides visual transparency into model signals. Green regions denote verified matching anchors; Yellow represents items requiring attention; Orange indicates moderate variance; Red marks high-anomaly regions such as modified identifiers.', 'Forensics', TRUE, 9) ON CONFLICT (id) DO NOTHING;

-- 4. INSERT ALL COMPLAINTS (1 records)
INSERT INTO public.complaints (id, verification_id, email, issue_type, description, status, response) VALUES ('CMP-2026-5F811', 'VRF-2026-B670B7', 'tester@example.com', 'Incorrect Verification Result', 'Submitting appeal to verify transcript records.', 'Resolved', 'Audit committee verified original records. Request resolved.') ON CONFLICT (id) DO NOTHING;